select jsonb_build_object('server',version(),'cron',current_setting('cron.launch_active_jobs'),'net',current_setting('pg_net.batch_size'),'listen',current_setting('listen_addresses'),'installed',(select jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'owner',r.rolname)order by e.extname)from pg_extension e join pg_namespace n on n.oid=e.extnamespace join pg_roles r on r.oid=e.extowner),'available',(select jsonb_agg(to_jsonb(t)order by name)from(select name,default_version,installed_version from pg_available_extensions where name in('pg_net','pg_cron','supabase_vault','pgsodium','pgcrypto','uuid-ossp','pg_stat_statements'))t));
